const Ins_P3 = () => {
  const context = useOutletContext();
  const resumeData = context?.ins?.data;
  return (
    <div className="summary-box">
      <h3>Policy Coverage Mapping Matrix</h3>
      <p>{resumeData ? `Missing keywords: ${resumeData.missing_keywords?.join(', ') || 'None'}` : "Standby for stream."}</p>
    </div>
  );
};
export default Ins_P3;
